def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    out = g.copy()
    emit(out.copy(), "Input: red lines cut the background into regions.")
    regs = components(g == bg)
    lines = components((g != bg))
    rid = -np.ones((H, W), int)
    for i, r in enumerate(regs):
        for (y, x) in r:
            rid[y, x] = i
    adj = {i: set() for i in range(len(regs))}
    for ln in lines:
        touch = set()
        for (y, x) in ln:
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny, nx = y+dy, x+dx
                if 0 <= ny < H and 0 <= nx < W and rid[ny, nx] >= 0:
                    touch.add(rid[ny, nx])
        for a in touch:
            for b in touch:
                if a != b:
                    adj[a].add(b)
    if not regs:
        return out
    # start region: one containing (or nearest to) the bottom-left corner
    best = None
    for y in range(H):
        for x in range(W):
            if rid[y, x] >= 0:
                d = (H-1-y) + x
                if best is None or d < best[0]:
                    best = (d, rid[y, x])
    start = best[1]
    col = {start: 5}
    order = [start]
    q = [start]
    while q:
        a = q.pop(0)
        for b in sorted(adj[a]):
            if b not in col:
                col[b] = 3 if col[a] == 5 else 5
                order.append(b)
                q.append(b)
    for i in range(len(regs)):
        if i not in col:
            col[i] = 5
            order.append(i)
    for i in order:
        for (y, x) in regs[i]:
            out[y, x] = col[i]
        emit(out.copy(), f"Fill region {i} with {col[i]} (alternating across red lines, bottom-left region = 5).")
    emit(out.copy(), "Final: regions coloured alternately 5/3.")
    return out
